class Solution:
    def countGoodRotations(self, nums: list[int]) -> int:
        n = len(nums)
        count = 0
        half = n // 2

        for i in range(n):
            first_half_sum = sum(nums[(i + j) % n] for j in range(half))
            second_half_sum = sum(nums[(i + j) % n] for j in range(half, n))

            if first_half_sum > second_half_sum:
                count += 1

        return count

