    def countGoodRotations(self, nums: list[int]) -> int:
        n = len(nums)
        half = n // 2
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        count = 0
        for k in range(n):
            first_sum = prefix[k + half] - prefix[k]
            second_sum = prefix[n] - prefix[k + half]
            if first_sum > second_sum:
                count += 1
        return count

