class Solution:
    def kthDigit(self, k: int) -> int:
        block = 0
        while k > 9:
            if block % 2 == 0:
                num_digits = 10 * len(str(10 * block))
            else:
                num_digits = 10 * len(str(10 * block + 9))
            if k <= num_digits:
                break
            k -= num_digits
            block += 1

        if block % 2 == 0:
            # Increasing order: 10*block to 10*block +9
            start = 10 * block
            end = 10 * block + 9
            for num in range(start, end + 1):
                num_str = str(num)
                if k <= len(num_str):
                    return int(num_str[k - 1])
                k -= len(num_str)
        else:
            # Decreasing order: 10*block +9 down to 10*block
            start = 10 * block + 9
            end = 10 * block
            for num in range(start, end - 1, -1):
                num_str = str(num)
                if k <= len(num_str):
                    return int(num_str[k - 1])
                k -= len(num_str)
        return -1  # should not reach here for valid k

