    def maxEqualPairs(self, nums: list[int]) -> int:
        from collections import defaultdict

        def count_pairs_after_replacement(x, y):
            pairs = 0
            for i in range(len(nums) - 1):
                if nums[i] == y and nums[i + 1] == y:
                    pairs += 1
                if (nums[i] == x and nums[i + 1] == y) or (nums[i] == y and nums[i + 1] == x):
