            return pairs

        max_pairs = 0
        # Calculate initial pairs without replacement
        for num in set(nums):
            count = nums.count(num)
            max_pairs = max(max_pairs, count - 1)

        # Try replacing each number x with every other number y
        for x in set(nums):
            for y in set(nums):
                if x == y:
                    continue
                pairs = count_pairs_after_replacement(x, y)
                max_pairs = max(max_pairs, pairs)

