class Solution:
    def maxEqualPairs(self, nums: list[int]) -> int:
        freq = defaultdict(int)
        for num in nums:
            freq[num] += 1

        original_pairs = 0
        for count in freq.values():
            original_pairs += count - 1

        max_pairs = original_pairs

        for x in freq:
            for y in freq:
                if x == y:
                    continue
                max_pairs = max(max_pairs, freq[x] + freq[y] - 1)

        return max_pairs

