from collections import defaultdict

class Solution:
    def rearrangeArray(self, nums: list[int]) -> list[int]:
        freq = defaultdict(int)
        for num in nums:
            freq[num] += 1

        ans = []
        while nums:
            distinct = set(nums)
            for num in sorted(distinct):
                if freq[num] > 0:
                    ans.append(num)
                    freq[num] -= 1
                    nums.remove(num)
        return ans

class Solution:
    def canTransform(self, source: list[int], target: list[int]) -> bool:
        if len(source) != len(target):
            return False
        if sum(source) != sum(target):
            return False
        return sorted(source) == sorted(target)
